using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // ───────────────────────────────────────────────
    // AddItem – happy path
    // ───────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);

        // Assert
        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDifferentItems_AllIncludedInTotal()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 3, 5.00m);

        // Assert
        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantityAccumulates()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 3, 10.00m);

        // Assert – quantity should be 2+3 = 5 × 10 = 50
        Assert.AreEqual(50.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuDifferentPrice_UsesLatestPrice()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 1, 15.00m);

        // Assert – quantity 3 × latest price 15 = 45
        Assert.AreEqual(45.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Allowed()
    {
        // Arrange & Act
        _cart.AddItem("FREE-ITEM", 1, 0.00m);

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // AddItem – validation errors
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null SKU")]
    [DataRow("", DisplayName = "empty SKU")]
    public void AddItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(sku!, 1, 10.00m));
        Assert.AreEqual("sku", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0, DisplayName = "zero quantity")]
    [DataRow(-1, DisplayName = "negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", quantity, 10.00m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", 1, -1.00m));
        Assert.AreEqual("price", ex.ParamName);
    }

    // ───────────────────────────────────────────────
    // RemoveItem – happy path
    // ───────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovedFromTotal()
    {
        // Arrange
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-002", 1, 5.00m);

        // Act
        _cart.RemoveItem("SKU-001");

        // Assert
        Assert.AreEqual(5.00m, _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // RemoveItem – validation errors
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null SKU")]
    [DataRow("", DisplayName = "empty SKU")]
    public void RemoveItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(sku!));
        Assert.AreEqual("sku", ex.ParamName);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _cart.RemoveItem("NO-SUCH-SKU"));
    }

    // ───────────────────────────────────────────────
    // CalculateTotal
    // ───────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _cart.AddItem("SKU-001", 3, 7.50m);
        Assert.AreEqual(22.50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 1, 10.00m);
        _cart.AddItem("B", 2, 20.00m);
        _cart.AddItem("C", 3, 5.00m);

        // 10 + 40 + 15 = 65
        Assert.AreEqual(65.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 1, 100.00m);
        _cart.AddItem("B", 1, 50.00m);
        _cart.RemoveItem("A");

        Assert.AreEqual(50.00m, _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // ApplyCoupon – happy path
    // ───────────────────────────────────────────────

    [TestMethod]
    public void ApplyCoupon_Save10_Applies10PercentDiscount()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Save20_Applies20PercentDiscount()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_Subtracts5Dollars()
    {
        _cart.AddItem("SKU-001", 1, 20.00m);
        _cart.ApplyCoupon("FLAT5");

        Assert.AreEqual(15.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_DoesNotGoBelowZero()
    {
        _cart.AddItem("SKU-001", 1, 3.00m);
        _cart.ApplyCoupon("FLAT5");

        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_BeforeAddingItems_DiscountAppliedOnCalculate()
    {
        // Apply coupon first, then add items
        _cart.ApplyCoupon("SAVE10");
        _cart.AddItem("SKU-001", 1, 50.00m);

        Assert.AreEqual(45.00m, _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // ApplyCoupon – validation errors
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null code")]
    [DataRow("", DisplayName = "empty code")]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException(string? code)
    {
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code!));
        Assert.AreEqual("code", ex.ParamName);
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException()
    {
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
        Assert.AreEqual("code", ex.ParamName);
    }

    // ───────────────────────────────────────────────
    // Combined / integration-style scenarios
    // ───────────────────────────────────────────────

    [TestMethod]
    public void AddItemsThenCouponThenTotal_CorrectDiscountedTotal()
    {
        _cart.AddItem("A", 2, 25.00m); // 50
        _cart.AddItem("B", 1, 30.00m); // 30
        _cart.ApplyCoupon("SAVE20");    // 80 × 0.80 = 64

        Assert.AreEqual(64.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddSameSkuMultipleTimes_ThenCalculateTotal_AccumulatedQuantity()
    {
        _cart.AddItem("SKU-X", 1, 12.00m);
        _cart.AddItem("SKU-X", 2, 12.00m);
        _cart.AddItem("SKU-X", 3, 12.00m);

        // 1+2+3 = 6 × 12 = 72
        Assert.AreEqual(72.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddRemoveAddCalculate_TracksStateCorrectly()
    {
        _cart.AddItem("A", 1, 10.00m);
        _cart.AddItem("B", 1, 20.00m);
        _cart.RemoveItem("A");
        _cart.AddItem("C", 2, 5.00m);

        // B=20 + C=10 = 30
        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ReplacePreviousCoupon_UsesLatest()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10"); // 10% off
        _cart.ApplyCoupon("SAVE20"); // replaced with 20% off

        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CalledMultipleTimes_ReturnsSameResult()
    {
        _cart.AddItem("SKU-001", 2, 15.00m);
        _cart.ApplyCoupon("FLAT5");

        var first = _cart.CalculateTotal();
        var second = _cart.CalculateTotal();

