1. namespace Store;
2. 
3. public sealed class ShoppingCart
4. {
5.     private readonly Dictionary<string, (int Quantity, decimal Price)> _items = new();
6.     private string? _couponCode;
7. 
8.     public void AddItem(string sku, int quantity, decimal price)
9.     {
10.         if (string.IsNullOrEmpty(sku))
11.             throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
12.         if (quantity <= 0)
13.             throw new ArgumentOutOfRangeException(nameof(quantity), quantity, "Quantity must be greater than zero.");
14.         if (price < 0)
15.             throw new ArgumentOutOfRangeException(nameof(price), price, "Price must be non-negative.");
16. 
17.         if (_items.TryGetValue(sku, out var existing))
18.             _items[sku] = (existing.Quantity + quantity, price);
19.         else
20.             _items[sku] = (quantity, price);
21.     }
22. 
23.     public void RemoveItem(string sku)
24.     {
25.         if (string.IsNullOrEmpty(sku))
26.             throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
27.         if (!_items.Remove(sku))
28.             throw new InvalidOperationException($"SKU '{sku}' is not in the cart.");
29.     }
30. 
31.     public decimal CalculateTotal()
32.     {
33.         decimal total = 0m;
34.         foreach (var item in _items.Values)
35.             total += item.Quantity * item.Price;
36. 
37.         if (_couponCode is not null)
38.         {
39.             total = _couponCode switch
40.             {
41.                 "SAVE10" => total * 0.90m,
42.                 "SAVE20" => total * 0.80m,
43.                 "FLAT5" => Math.Max(0m, total - 5m),
44.                 _ => total
45.             };
46.         }
47. 
48.         return total;
49.     }
50. 
51.     public void ApplyCoupon(string code)
52.     {
53.         if (string.IsNullOrEmpty(code))
54.             throw new ArgumentException("Coupon code cannot be null or empty.", nameof(code));
55. 
56.         if (code is not ("SAVE10" or "SAVE20" or "FLAT5"))
57.             throw new ArgumentException($"Unknown coupon code: '{code}'.", nameof(code));
58. 
59.         _couponCode = code;
60.     }
61. }
