     }

     [TestMethod]
     public void AddItem_ZeroPrice_Allowed()
     {
         // Arrange & Act – add a priced item first so total is non-zero without the free item
         _cart.AddItem("PAID", 1, 10.00m);
         _cart.AddItem("FREE-ITEM", 1, 0.00m);

         // Assert – total reflects only the paid item; free item was truly added (removing it doesn't throw)
         Assert.AreEqual(10.00m, _cart.CalculateTotal());
         _cart.RemoveItem("FREE-ITEM"); // proves item was stored
         Assert.AreEqual(10.00m, _cart.CalculateTotal());
     }

